@startuml

class User {
  + UserID : int
  + Name : string
  + Address : string
  + Birthday : date
}

class BusinessOwner {}
class HungryCustomer {
  + DeliveryAddress : string
}
class Entertainer {
  + StageName : string
  + Bio : string
  + PricePer30Minutes : double
}

class PizzaRestaurant {
  + ZipCode : int
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : time[]
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : double
}

class Order {
  + OrderID : int
  + DateAndTimePlaced : datetime
  + LatestDeliveryTime : datetime
  + NumberOfPeople : int
  + EntertainmentType : string
  + Duration : time
}

PizzaRestaurant "1" -- "*" Pizza
BusinessOwner --|> User
HungryCustomer --|> User
Entertainer --|> User
PizzaRestaurant "0..*" -- "1" Entertainer
Order "1" -- "1" HungryCustomer
Order "1" -- "1" Pizza
Order "1" -- "1" EntertainmentType

@enduml

